+        assert.ok(cliCalls.some(function(c) { return c.indexOf('WIP auto-save') !== -1; }) ||
+                  cliCalls.filter(function(c) { return c.indexOf('git commit') === 0; }).length >= 1,
+            'the WIP commit still landed on the remote');
+    });
